"""Golden assertions are hand-specified from the raw fixture, not generated by the parser."""

import hashlib
import json
import os
import sqlite3
import subprocess
import sys
from decimal import Decimal

import pytest
from sqlalchemy.exc import IntegrityError

from stock_research_ai.adapters.raw_artifacts import FileRawArtifactStore
from stock_research_ai.adapters.sqlite import SQLiteDatabase
from stock_research_ai.bootstrap import extract_snapshot, initialize_database
from stock_research_ai.config import Settings
from stock_research_ai.domain.extraction import CompanyExtractionResult, ExtractionRequest

URL = "https://www.screener.in/company/YESBANK/consolidated/"


async def test_yesbank_golden_pipeline(yesbank_result, fixture_dir, tmp_path):
    expected = json.loads((fixture_dir / "expected_yesbank.json").read_text())
    result = yesbank_result
    assert result.company is not None
    company = result.company
    for field in ("name", "source_company_key", "reporting_scope"):
        assert getattr(company, field) == expected["identity"][field]
    assert {
        listing.exchange: listing.symbol or listing.exchange_identifier
        for listing in company.listings
    } == {
        "NSE": expected["identity"]["NSE"],
        "BSE": expected["identity"]["BSE"],
    }
    for metric, value in expected["top_metrics"].items():
        assert next(r for r in result.top_metrics if r.metric_id == metric).value == Decimal(value)
    for check in expected["observations"]:
        record = next(
            r
            for r in getattr(result, check["section"])
            if r.original_label == check["label"] and r.period.fiscal_label == check["period"]
        )
        assert record.value == (Decimal(check["value"]) if check["value"] is not None else None)
        assert record.value_status == check.get("status", "available")
        if "end_date" in check:
            assert record.period.end_date.isoformat() == check["end_date"]
        assert record.provenance.raw_artifact_id == result.raw_artifacts[0].id
        assert record.provenance.source_location.locator.startswith("#")
        assert record.original_value is not None
    for check in expected["holdings"]:
        records = [
            h.observation
            for h in result.shareholding.holdings
            if h.category == check["category"]
            and h.observation.period.fiscal_label == check["period"]
        ]
        assert records and all(r.value == Decimal(check["value"]) for r in records)
        assert all(r.unit.kind == "percent" for r in records)
    count = expected["shareholder_count"]
    r = next(
        r
        for r in result.shareholding.shareholder_counts
        if r.period.fiscal_label == count["period"]
    )
    assert r.value == Decimal(count["value"]) and r.unit.kind == "number"
    for check in expected["documents"]:
        doc = next(d for d in result.documents if d.link.original_href == check["href"])
        assert doc.document_type == check["type"]
        assert doc.link.resolved_url == check["href"]
        assert doc.provenance.raw_artifact_id == result.raw_artifacts[0].id
    assert {c.section: [c.presence, c.parse_status] for c in result.coverage.sections} == expected[
        "coverage"
    ]
    peers = next(c for c in result.coverage.sections if c.section == "PEERS")
    assert "loading" in peers.issues[0].message
    artifact = result.raw_artifacts[0]
    content = (fixture_dir / "yesbank_consolidated.html").read_bytes()
    assert artifact.content_sha256 == hashlib.sha256(content).hexdigest()
    store = FileRawArtifactStore(tmp_path / "artifacts")
    assert await store.read(artifact) == content
    assert (tmp_path / "export/raw" / f"{artifact.content_sha256}.html").read_bytes() == content
    exported = CompanyExtractionResult.model_validate_json(
        (tmp_path / "export/normalized/extraction.json").read_text()
    )
    database = SQLiteDatabase(tmp_path / "proof.sqlite3")
    try:
        assert await database.extractions.get_extraction(result.metadata.id) == result == exported
    finally:
        await database.close()


async def test_second_company_standalone(fixture_dir, tmp_path):
    settings = Settings(database_path=tmp_path / "infy.sqlite3", artifact_path=tmp_path / "raw")
    await initialize_database(settings)
    result = await extract_snapshot(
        settings,
        ExtractionRequest(
            provider="screener",
            url="https://www.screener.in/company/INFY/",
            replay_path=fixture_dir / "infy_standalone.html",
        ),
        tmp_path / "output",
    )
    assert result.company.name == "Infosys Ltd"
    assert result.company.reporting_scope == "standalone"
    assert any(r.metric_id == "operating_profit" for r in result.quarterly)
    assert any(r.metric_id == "sales" for r in result.profit_loss)
    assert all(r.reporting_scope == "standalone" for r in result.quarterly)
    assert (
        next(c for c in result.coverage.sections if c.section == "QUARTERLY").parse_status
        == "SUCCESS"
    )


async def test_snapshot_history_and_identity_binding(yesbank_result, fixture_dir, tmp_path):
    first = yesbank_result
    settings = Settings(
        database_path=tmp_path / "proof.sqlite3", artifact_path=tmp_path / "artifacts"
    )
    changed = tmp_path / "changed.html"
    changed.write_bytes(
        (fixture_dir / "yesbank_consolidated.html").read_bytes().replace(b"6,445", b"6,446", 1)
    )
    second = await extract_snapshot(
        settings,
        ExtractionRequest(provider="screener", url=URL, replay_path=changed),
        tmp_path / "second",
    )
    assert second.company.company_id == first.company.company_id
    assert second.metadata.id != first.metadata.id
    assert second.raw_artifacts[0].content_sha256 != first.raw_artifacts[0].content_sha256
    assert second.quarterly[0].value == first.quarterly[0].value + 1
    assert second.quarterly[0].series_key == first.quarterly[0].series_key
    assert second.quarterly[0].id != first.quarterly[0].id
    database = SQLiteDatabase(settings.database_path)
    try:
        assert await database.extractions.get_extraction(first.metadata.id) == first
        assert await database.extractions.get_extraction(second.metadata.id) == second
        registered = await database.repository.get(first.company.company_id)
        assert {listing.exchange for listing in registered.listings} == {"NSE", "BSE"}
        with pytest.raises(IntegrityError):
            await database.extractions.save_extraction(first)
    finally:
        await database.close()
    with sqlite3.connect(settings.database_path) as db:
        tables = {r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        assert tables == {
            "companies",
            "listings",
            "company_source_keys",
            "source_retrievals",
            "raw_artifacts",
            "extractions",
            "documents",
            "document_extractions",
            "market_instruments",
            "market_extractions",
            "publications",
            "publication_snapshots",
            "macro_series",
            "macro_snapshots",
            "calculation_snapshots",
            "market_calculation_snapshots",
        }
        for table, count in {
            "companies": 1,
            "listings": 2,
            "company_source_keys": 1,
            "source_retrievals": 2,
            "raw_artifacts": 2,
            "extractions": 2,
        }.items():
            assert db.execute(f"SELECT count(*) FROM {table}").fetchone()[0] == count
    assert (
        await FileRawArtifactStore(tmp_path / "artifacts").read(first.raw_artifacts[0])
        == (fixture_dir / "yesbank_consolidated.html").read_bytes()
    )


def test_real_cli_offline(fixture_dir, tmp_path):
    # Guard the subprocess too: an accidental live call must fail acceptance.
    guard = tmp_path / "guard"
    guard.mkdir()
    (guard / "sitecustomize.py").write_text(
        "import socket\n"
        "def blocked(*args, **kwargs): raise RuntimeError('CLI acceptance must stay offline')\n"
        "socket.create_connection = blocked\nsocket.socket.connect = blocked\n"
    )
    env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1", "PYTHONPATH": str(guard)}
    base = [
        sys.executable,
        "-B",
        "-m",
        "stock_research_ai",
        "--database",
        str(tmp_path / "cli.sqlite3"),
    ]
    subprocess.run([*base, "init-db"], check=True, capture_output=True, env=env)
    output = tmp_path / "cli-output"
    command = [
        *base,
        "extract-screener",
        URL,
        "--html",
        str(fixture_dir / "yesbank_consolidated.html"),
        "--output",
        str(output),
    ]
    completed = subprocess.run(command, capture_output=True, text=True, env=env)
    assert completed.returncode == 3, completed.stderr
    assert "PEERS: UNAVAILABLE/NOT_ATTEMPTED" in completed.stdout
    snapshot = CompanyExtractionResult.model_validate_json(
        (output / "normalized/extraction.json").read_text()
    )
    assert snapshot.company.name == "Yes Bank Ltd"
    assert {p.name for p in (output / "normalized").iterdir()} == {
        "extraction.json",
        "company.json",
        "quarterly.json",
        "profit_loss.json",
        "balance_sheet.json",
        "cashflow.json",
        "ratios.json",
        "shareholding.json",
        "peers.json",
        "documents.json",
    }
    assert (output / "coverage.json").is_file() and (output / "raw/manifest.json").is_file()
    repeated = subprocess.run(command, capture_output=True, text=True, env=env)
    assert repeated.returncode == 1 and "empty directory" in repeated.stderr


@pytest.mark.parametrize(
    "status,html,content_type",
    [
        (403, b"<html>Access denied</html>", "text/html"),
        (200, b"<html>Login required</html>", "text/html"),
        (200, b"\xff\xfe", "text/html; charset=utf-8"),
        (200, b'{"error":true}', "application/json"),
    ],
)
async def test_failed_acquisition_still_exports_evidence_and_coverage(
    status, html, content_type, tmp_path
):
    import httpx

    from stock_research_ai.adapters.screener.source import ScreenerSource

    settings = Settings(database_path=tmp_path / "db.sqlite3", artifact_path=tmp_path / "raw")
    await initialize_database(settings)
    source = ScreenerSource(
        httpx.MockTransport(
            lambda request: httpx.Response(
                status, content=html, headers={"content-type": content_type}
            )
        )
    )
    result = await extract_snapshot(
        settings, ExtractionRequest(provider="screener", url=URL), tmp_path / "out", source
    )
    assert result.coverage.overall == "FAILED"
    assert result.company is None
    assert len(result.coverage.sections) == 10
    assert all(c.parse_status != "SUCCESS" for c in result.coverage.sections)
    assert await FileRawArtifactStore(tmp_path / "raw").read(result.raw_artifacts[0]) == html
    assert json.loads((tmp_path / "out/coverage.json").read_text())["overall"] == "FAILED"
    database = SQLiteDatabase(settings.database_path)
    try:
        assert await database.extractions.get_extraction(result.metadata.id) == result
    finally:
        await database.close()


async def test_mock_http_runs_complete_pipeline(fixture_dir, tmp_path):
    import httpx

    from stock_research_ai.adapters.screener.source import ScreenerSource

    content = (fixture_dir / "yesbank_consolidated.html").read_bytes()
    settings = Settings(database_path=tmp_path / "db.sqlite3", artifact_path=tmp_path / "raw")
    await initialize_database(settings)
    source = ScreenerSource(
        httpx.MockTransport(
            lambda request: httpx.Response(
                200, content=content, headers={"content-type": "text/html; charset=utf-8"}
            )
        )
    )
    result = await extract_snapshot(
        settings, ExtractionRequest(provider="screener", url=URL), tmp_path / "out", source
    )
    assert (
        result.company.name == "Yes Bank Ltd" and result.company.reporting_scope == "consolidated"
    )
    assert result.raw_artifacts[0].representation == "decoded_http_body"
    assert result.retrievals[0].mode == "http"
    assert await FileRawArtifactStore(tmp_path / "raw").read(result.raw_artifacts[0]) == content


async def test_concurrent_acquisitions_reuse_identity(fixture_dir, tmp_path):
    import asyncio

    settings = Settings(database_path=tmp_path / "db.sqlite3", artifact_path=tmp_path / "raw")
    await initialize_database(settings)
    request = ExtractionRequest(
        provider="screener", url=URL, replay_path=fixture_dir / "yesbank_consolidated.html"
    )
    first, second = await asyncio.gather(
        extract_snapshot(settings, request, tmp_path / "first"),
        extract_snapshot(settings, request, tmp_path / "second"),
    )
    assert first.company.company_id == second.company.company_id
    assert first.metadata.id != second.metadata.id
    assert first.raw_artifacts[0].content_sha256 == second.raw_artifacts[0].content_sha256
    assert first.raw_artifacts[0].id != second.raw_artifacts[0].id
